"""Quick mock LangWatch server to verify run_evaluation.py flow.

Listens on 127.0.0.1:8765 and records every request to a JSON file so we can
inspect what the evaluation script sent. Only implements the endpoints the
script actually touches.
"""
import json
import os
import threading
from http.server import BaseHTTPRequestHandler, HTTPServer

RECORDS_PATH = "/tmp/langwatch_requests.jsonl"

_records: list = []
_lock = threading.Lock()


class _Handler(BaseHTTPRequestHandler):
    def log_message(self, format, *args):  # silence stderr noise
        return

    def _read_body(self) -> bytes:
        length = int(self.headers.get("Content-Length", "0") or 0)
        return self.rfile.read(length) if length else b""

    def _record(self, method: str, path: str, body: dict) -> None:
        with _lock:
            _records.append({"method": method, "path": path, "body": body})

    def _send(self, payload: dict, status: int = 200) -> None:
        data = json.dumps(payload).encode("utf-8")
        self.send_response(status)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(data)))
        self.end_headers()
        self.wfile.write(data)

    def do_POST(self):  # noqa: N802
        raw = self._read_body()
        try:
            body = json.loads(raw or b"{}")
        except Exception:
            body = {"_raw": raw.decode("utf-8", errors="replace")}
        self._record("POST", self.path, body)

        if self.path == "/api/experiment/init":
            return self._send({
                "path": "/mock/path",
                "slug": body.get("experiment_slug") or body.get("experiment_name") or "mock-slug",
            })
        if self.path.startswith("/api/evaluations/") and self.path.endswith("/evaluate"):
            return self._send({"status": "processed", "score": 0.9})
        if self.path == "/api/evaluations/batch/log_results":
            return self._send({"ok": True})
        return self._send({"ok": True, "path": self.path})

    def do_GET(self):  # noqa: N802
        self._record("GET", self.path, {})
        return self._send({"ok": True})


def main():
    open(RECORDS_PATH, "w").close()
    server = HTTPServer(("127.0.0.1", 8765), _Handler)

    def persist():
        with open(RECORDS_PATH, "a") as fh:
            for r in _records:
                fh.write(json.dumps(r) + "\n")

    import atexit
    atexit.register(persist)
    print("mock langwatch listening on http://127.0.0.1:8765")
    server.serve_forever()


if __name__ == "__main__":
    main()

